package com.lamontlabs.quantravision.next;

import android.app.Activity;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.widget.*;
import org.json.*;
import java.io.*;

/** Evaluation ships with the app, including all labeled misses. */
public final class EvidenceActivity extends Activity {
    static JSONObject report(android.content.Context c){try{return new JSONObject(AppStore.readText(c.getAssets().open("evaluation/report.json"),400000));}catch(Exception e){return null;}}
    static String coverage(android.content.Context c,String id){JSONObject r=report(c);JSONObject patterns=r==null?null:r.optJSONObject("patterns"),p=patterns==null?null:patterns.optJSONObject(id);if(p==null||p.optInt("targets")==0)return "Synthetic rule checks exist, but no labeled external-image target covers this rule in this build. Real-chart recognition accuracy is unestablished.";return p.optInt("matched")+" of "+p.optInt("targets")+" labeled external-image targets matched; "+p.optInt("missed")+" missed. This small development set is not a general accuracy estimate.";}
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=Ui.column(this);root.setBackgroundColor(Ui.BG);root.setFitsSystemWindows(true);ScrollView scroll=new ScrollView(this);LinearLayout body=Ui.column(this);body.setPadding(d(24),d(22),d(24),d(32));scroll.addView(body);root.addView(scroll);TextView back=Ui.text(this,"‹  Back",13,Ui.LIME,true);back.setContentDescription("Back from evaluation");back.setPadding(0,d(12),0,d(20));back.setOnClickListener(v->finish());Ui.add(body,back);Ui.add(body,Ui.eyebrow(this,"RECORDED OUTCOMES"));Ui.gap(body,12);Ui.add(body,Ui.display(this,"The evidence ledger.",37));Ui.gap(body,14);Ui.add(body,Ui.text(this,"Real inputs. Every labeled miss stays visible.",14,Ui.MUTED,false));Ui.gap(body,24);JSONObject r=report(this);if(r==null){Ui.add(body,Ui.text(this,"Evaluation has not been packaged. No recognition-accuracy claim is available.",15,Ui.RED,false));setContentView(root);return;}
        JSONObject count=r.optJSONObject("counts");if(count!=null){LinearLayout card=Ui.card(this);Ui.add(card,Ui.mono(this,count.optInt("sourceCharts")+" SOURCE CHARTS / "+count.optInt("cases")+" CASES",10,Ui.LIME));Ui.gap(card,14);Ui.add(card,Ui.text(this,count.optInt("matchedTargets")+" targets matched · "+count.optInt("missedTargets")+" missed",16,Ui.INK,true));Ui.gap(card,8);Ui.add(card,Ui.text(this,count.optInt("forbiddenPatternFlags")+" forbidden flags in "+count.optInt("negativePatternChecks")+" negative-pattern checks. "+count.optInt("falseReadableInputs")+" false readings in "+count.optInt("negativeReadChecks")+" non-chart checks.",12,Ui.MUTED,false));Ui.add(body,card);Ui.gap(body,20);}
        Ui.add(body,Ui.text(this,r.optString("limitations"),12,Ui.MUTED,false));Ui.gap(body,24);JSONArray cases=r.optJSONArray("cases");if(cases!=null)for(int i=0;i<cases.length();i++){JSONObject item=cases.optJSONObject(i);if(item==null)continue;LinearLayout card=Ui.card(this);String status=item.optString("status");boolean ok="matched".equals(status)||"negative_pass".equals(status);Ui.add(card,Ui.mono(this,status.replace('_',' ').toUpperCase(java.util.Locale.ROOT),10,ok?Ui.TEAL:Ui.RED));Ui.gap(card,10);Ui.add(card,Ui.text(this,item.optString("title"),15,Ui.INK,true));Ui.gap(card,8);Ui.add(card,Ui.text(this,item.optString("outcome"),12,Ui.MUTED,false));Ui.gap(card,10);Ui.add(card,Ui.mono(this,item.optString("publisher"),9,Ui.MUTED));String source=item.optString("source");if(source.startsWith("https://")){Ui.gap(card,14);TextView link=Ui.text(this,"Original source  ↗",12,Ui.LIME,true);link.setPadding(0,d(10),0,d(10));link.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(source)));}catch(ActivityNotFoundException ignored){}});Ui.add(card,link);}Ui.add(body,card);Ui.gap(body,12);}setContentView(root);}
    private int d(float n){return Ui.dp(this,n);}
}
